Method.Source:
/// <summary>
/// Runs every test case in the given suite in Sequence order. For each case
/// the orchestrator dispatches to three phases:
///   - PreProcessClass  (required) - runnable class, static main(Args)
///   - RunnerClass      (required) - extends XAPI_APIRunnerBase, executes the API call and logs it
///   - Post-process     (optional) - resolved via XAPI_APIPostProcessorBase::construct(API)
/// Independent suites continue past failures; Chained suites stop on the first failure.
/// </summary>
/// <param name = "_suiteId">Suite to run.</param>
public static void run(str _suiteId)
{
    XAPI_TestSuite       suite;
    XAPI_TestCase        testCase;
    XAPI_TestStepContext context;
    XAPI_SuiteType       suiteType;
    boolean              chainBroken;
    boolean              stepFailed;

    select firstonly suite
        where suite.SuiteId == _suiteId;

    if (!suite.RecId)
    {
        error(strFmt("Suite %1 not found.", _suiteId));
        return;
    }

    suiteType = suite.SuiteType;
    context   = XAPI_TestStepContext::construct(_suiteId, newGuid());

    while select testCase
        order by Sequence asc
        where testCase.SuiteId == _suiteId
    {
        if (chainBroken)
        {
            break;
        }

        stepFailed = false;
        context.setCurrentCase(testCase);

        // --- Pre-process phase ---
        XAPI_APILogValues preLog;
        preLog.SessionId = context.parmSessionId();
        preLog.Sequence  = testCase.Sequence;
        preLog.LogType   = XAPI_LogType::PreProcess;

        try
        {
            if (testCase.PreProcessClass != '')
            {
                //throw Error("No preprocess class found");
                XAPI_SuiteOrchestrator::runMain(testCase.PreProcessClass);
            }


            preLog.Status  = XAPI_APIStatus::Success;
            preLog.Message = strFmt("PreProcess %1 completed.", testCase.PreProcessClass);
        }
        catch (Exception::Error)
        {
            preLog.Status       = XAPI_APIStatus::Error;
            preLog.Message      = strFmt("PreProcess %1 failed.", testCase.PreProcessClass);
            preLog.ErrorMessage = infolog().text();

            stepFailed = true;
            if (suiteType == XAPI_SuiteType::Chained)
            {
                chainBroken = true;
            }
        }
        preLog.insert();

        // --- API Runner phase (logs its own rows via execute()) ---
        if (!stepFailed)
        {
            XAPI_APIStatus runnerStatus;
            try
            {
                runnerStatus = XAPI_SuiteOrchestrator::runStep(testCase.RunnerClass, context);
            }
            catch (Exception::Error)
            {
                runnerStatus = XAPI_APIStatus::Error;
                warning(strFmt("Suite %1 - Seq %2 [%3] runner failed.",
                    _suiteId, testCase.Sequence, testCase.RunnerClass));
            }

            if (runnerStatus == XAPI_APIStatus::Error)
            {
                stepFailed = true;
                if (suiteType == XAPI_SuiteType::Chained)
                {
                    chainBroken = true;
                }
            }
        }
        else
        {
            XAPI_APILogValues notRunLog;
            notRunLog.SessionId = context.parmSessionId();
            notRunLog.Sequence  = testCase.Sequence;
            notRunLog.LogType   = XAPI_LogType::APIRunner;
            notRunLog.Status    = XAPI_APIStatus::NotRun;
            notRunLog.insert();
        }

        // --- Post-process phase ---
        if (testCase.PostProcessBatchClass != '')
        {
            XAPI_APILogValues postLog;
            postLog.SessionId = context.parmSessionId();
            postLog.Sequence  = testCase.Sequence;
            postLog.LogType   = XAPI_LogType::PostProcess;

            if (!stepFailed)
            {
                try
                {
                    XAPI_SuiteOrchestrator::runPostStep(testCase.PostProcessBatchClass);

                    postLog.Status  = XAPI_APIStatus::Success;
                    postLog.Message = strFmt("PostProcess %1 completed.", testCase.PostProcessBatchClass);
                }
                catch (Exception::Error)
                {
                    postLog.Status       = XAPI_APIStatus::Error;
                    postLog.Message      = strFmt("PostProcess %1 failed.", testCase.PostProcessBatchClass);
                    postLog.ErrorMessage = infolog().text();

                    if (suiteType == XAPI_SuiteType::Chained)
                    {
                        chainBroken = true;
                    }
                }
            }
            else
            {
                postLog.Status = XAPI_APIStatus::NotRun;
            }
            postLog.insert();
        }

        if (!stepFailed)
        {
            info(strFmt("Suite %1 - Seq %2 [%3] completed.",
                _suiteId, testCase.Sequence, testCase.RunnerClass));
        }
    }

    info(strFmt("Suite %1 run %2 complete.", _suiteId, guid2Str(context.parmSessionId())));
}

/// <summary>
/// Invokes the named class's static main(Args) entry point. Used for pre and
/// post-process steps, which follow the standard runnable-class pattern and
/// do not extend any base.
/// </summary>
private static void runMain(str _className)
{
    ClassId      classId;
    SysDictClass dictClass;
    Args         args;

    classId = className2Id(_className);
    if (!classId)
    {
        throw error(strFmt("Class %1 not found.", _className));
    }

    dictClass = new SysDictClass(classId);
    args      = new Args();
    dictClass.callStatic('main', args);
}

/// <summary>
/// Instantiates the named class (must extend XAPI_APIRunnerBase) and invokes
/// execute(context). Throws if the class can't be resolved or doesn't conform.
/// </summary>
private static XAPI_APIStatus runStep(str _className, XAPI_TestStepContext _ctx)
{
    ClassId            classId;
    SysDictClass       dictClass;
    XAPI_APIRunnerBase runner;

    if (_className == '')
    {
        throw error("Test case is missing a runner class name.");
    }

    classId = className2Id(_className);
    if (!classId)
    {
        throw error(strFmt("Class %1 not found.", _className));
    }

    dictClass = new SysDictClass(classId);
    runner    = dictClass.makeObject() as XAPI_APIRunnerBase;
    if (!runner)
    {
        throw error(strFmt("Class %1 does not extend XAPI_APIRunnerBase.", _className));
    }

    return runner.execute(_ctx);
}

/// <summary>
/// Instantiates the named post-process class and invokes its run() method.
/// </summary>
private static void runPostStep(str _className)
{
    ClassId      classId;
    SysDictClass dictClass;
    Object       obj;

    classId = className2Id(_className);
    if (!classId)
    {
        throw error(strFmt("Class %1 not found.", _className));
    }

    dictClass = new SysDictClass(classId);
    obj       = dictClass.makeObject();
    dictClass.callObject('run', obj);
}
